import java.util.*;

class Solution {
    public int lastStoneWeight(int[] stones) {
        List<Integer> list = new ArrayList<>();
        for (int s : stones) list.add(s);

        while (list.size() > 1) {
            Collections.sort(list);
            int a = list.remove(list.size() - 1);
            int b = list.remove(list.size() - 1);
            if (a != b) list.add(a - b);
        }
        return list.isEmpty() ? 0 : list.get(0);
    }
}

import java.util.*;

class Solution {
    public int lastStoneWeight(int[] stones) {
        PriorityQueue<Integer> heap = new PriorityQueue<>(Collections.reverseOrder());
        for (int s : stones) heap.offer(s);

        while (heap.size() > 1) {
            int a = heap.poll();
            int b = heap.poll();
            if (a != b) heap.offer(a - b);
        }
        return heap.isEmpty() ? 0 : heap.peek();
    }
}

class Solution {
    public int lastStoneWeight(int[] stones) {
        int[] cnt = new int[1001];
        for (int s : stones) cnt[s]++;

        for (int i = 1000; i > 0; i--) {
            if (cnt[i] == 0) continue;
            if (cnt[i] % 2 == 0) {
                cnt[i] = 0;
                continue;
            }
            int j = i - 1;
            while (j > 0 && cnt[j] == 0) j--;
            if (j == 0) {
                cnt[i] = 1;
                continue;
            }
            cnt[i] = 0;
            cnt[j]--;
            cnt[i - j]++;
        }

        for (int i = 1000; i > 0; i--) {
            if (cnt[i] > 0) return i;
        }
        return 0;
    }
}
